pub fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Compute S(k) = sum_{i=1}^k a[i], where
    // a[i] = -i if i is odd, +i if i is even.
    // Closed‐form:
    //   S(k) =  k/2      if k is even
    //         = -(k+1)/2 if k is odd
    fn prefix_sum(k: i8) -> i16 {
        let k16 = k as i16;
        if k16 % 2 == 0 {
            k16 / 2
        } else {
            -(k16 + 1) / 2
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // sum over [l..=r] = S(r) - S(l-1)
            let total = prefix_sum(r) - prefix_sum(l - 1);
            total as i8
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_small_ranges() {
        // a = [-1, +2, -3, +4, -5, +6, ...]
        // prefix sums: [ -1, 1, -2, 2, -3, 3, ... ]
        let queries = vec![(1, 1), (1, 2), (1, 3), (2, 5), (3, 6), (4, 4)];
        let ans = solve(queries);
        assert_eq!(ans, vec![-1, 1, -2, -2, 2, 4]);
    }

    #[test]
    fn test_edge_cases() {
        // single even, single odd, larger spans
        let queries = vec![(5, 5), (6, 6), (1, 127), (2, 127), (127, 127)];
        let ans = solve(queries);
        // a[5] = -5, a[6] = +6
        // S(127) = -(128/2) = -64, S(0)=0 => -64
        // S(127) - S(1) = -64 - (-1) = -63
        // a[127] = -(128/2) = -64
        assert_eq!(ans, vec![-5, 6, -64, -63, -64]);
    }
}